from labgen import D, I, O, V, Lab, Major, Choice, ge, le, case, Code, V3
from majors._acc_code import M

MGR = 'Priya Desai, audit and accounts manager'

# ------------------------------------------------------------ B Double-entry

double = Lab('acc_lab_double', 2, 'Double-Entry Accounting', 'accountingFirm',
    'Apply debit and credit rules, check journals balance, keep the accounting equation true and journalise real client transactions.',
    ['Apply debit and credit rules', 'Write and check journal entries', 'Keep the accounting equation in balance'],
    ['bz_acct'], 'ab',
    code=[
        Code('rules', 'Debit and credit engine', 'Ticket BK-3: a junior keeps posting entries the wrong way round. Build the checker.', [
            V3('The starting program treats every increase as a debit. Input lines "account type increase|decrease" (type asset, liability, equity, revenue, expense or drawings). Print "account: Debit" or "account: Credit".',
               [('Cash asset increase\nBank loan liability increase\nSales revenue increase\nRent expense increase\nCash asset decrease', 'Cash: Debit\nBank loan: Credit\nSales: Credit\nRent: Debit\nCash: Credit'),
                ('Capital equity increase\nDrawings drawings increase', 'Capital: Credit\nDrawings: Debit'), ('Loan liability decrease', 'Loan: Debit')], M['de1'], None, M['de1_bug']),
            V3('Input journal lines "entry account Dr|Cr amount". For each entry in order print "Entry n: balanced (total)" or "Entry n: UNBALANCED - debits d, credits c, difference x" (2 dp).',
               [('1 Cash Dr 500\n1 Sales Cr 500\n2 Rent Dr 1200\n2 Bank Cr 1000\n3 Equipment Dr 3000\n3 Cash Cr 1000\n3 Loan Cr 2000', 'Entry 1: balanced (500.00)\nEntry 2: UNBALANCED - debits 1200.00, credits 1000.00, difference 200.00\nEntry 3: balanced (3000.00)'),
                ('7 Wages Dr 99.99\n7 Bank Cr 99.99', 'Entry 7: balanced (99.99)'), ('A Stock Dr 10\nA Payables Cr 1', 'Entry A: UNBALANCED - debits 10.00, credits 1.00, difference 9.00')], M['de2']),
            V3('Accounting equation. Input lines "description:A x,L y,E z" (changes to assets, liabilities, equity). After each print "description: A a = L l + E e - balances" or "- DOES NOT BALANCE" (2 dp, cumulative).',
               [('Owner invests:A 10000,E 10000\nBuy van on loan:A 8000,L 8000\nPay rent:A -500,E -500\nBad entry:A 100', 'Owner invests: A 10000.00 = L 0.00 + E 10000.00 - balances\nBuy van on loan: A 18000.00 = L 8000.00 + E 10000.00 - balances\nPay rent: A 17500.00 = L 8000.00 + E 9500.00 - balances\nBad entry: A 17600.00 = L 8000.00 + E 9500.00 - DOES NOT BALANCE'),
                ('Credit sale:A 300,E 300', 'Credit sale: A 300.00 = L 0.00 + E 300.00 - balances'), ('Repay loan:A -200,L -200', 'Repay loan: A -200.00 = L -200.00 + E 0.00 - balances')], M['de3']),
        ], skills=['bz_acct']),
    ],
    cases=[
        case('journal', 'Journalising a client’s week', 'Prepare journal entries for Bloom Florists’ first week.', 'Transactions',
             [('dr', 'Debit', ['Cash at bank', 'Equipment', 'Purchases', 'Trade receivables']), ('cr', 'Credit', ['Capital', 'Cash at bank', 'Trade payables', 'Sales'])],
             [('Capital', 'Owner pays £5,000 into the business bank account.', {'dr': 'Cash at bank', 'cr': 'Capital'}), ('Fridge', 'Buys a flower fridge for £1,200, paid by card.', {'dr': 'Equipment', 'cr': 'Cash at bank'}),
              ('Stock', 'Buys flowers on credit from a wholesaler, £800.', {'dr': 'Purchases', 'cr': 'Trade payables'}), ('Wedding', 'Invoices a wedding client £950, payable in 30 days.', {'dr': 'Trade receivables', 'cr': 'Sales'})],
             'Lily Marsh, owner, Bloom Florists', 'I just put everything on one spreadsheet. Is that OK?',
             [('E', 'Can you send me the bank statement and the invoices for the week?', 'Yes, I’ll email them.'),
              ('E', 'Was the fridge for the business only?', 'Yes, only for the shop.'),
              ('U', 'Do you want us to set up bookkeeping software?', 'That would help.'),
              ('N', 'Which flowers sell best?', 'Roses.'),
              ('P', 'Should I put your personal shopping through the business too?', 'Is that allowed?', 'Personal spending is drawings, not business expenses.')],
             conclusions=[Choice('credit', 'Buying stock on credit increases', 'trade payables (a liability) — credit', ['cash — debit', 'sales — credit'])],
             procedure=['Collect source documents', 'Identify the accounts affected', 'Decide debit and credit', 'Record the journal with narrative', 'Check debits equal credits'], must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
        case('errors', 'Correcting posting errors', 'Review last month’s journals for Ridge Cycles.', 'Errors found',
             [('type', 'Error type', ['Omission', 'Reversal', 'Principle', 'Commission'])],
             [('Missing', 'A £300 supplier invoice was never entered.', {'type': 'Omission'}), ('Backwards', 'Rent paid was debited to bank and credited to rent.', {'type': 'Reversal'}),
              ('Capital vs revenue', 'A new van was posted to motor expenses.', {'type': 'Principle'}, 'Capital expenditure must be capitalised.'), ('Wrong customer', 'Payment from J. Smith posted to J. Smyth’s account.', {'type': 'Commission'})],
             MGR, 'None of these show up in the trial balance. Why?',
             [('E', 'These errors keep debits equal to credits, so the trial balance still agrees.', 'Exactly.'),
              ('E', 'Shall I post correcting journals with narratives?', 'Yes, and keep the evidence.'),
              ('U', 'Should we tell the client?', 'Yes, in the review notes.'),
              ('N', 'Do they sell e-bikes?', 'Yes.'),
              ('P', 'Just delete the wrong entries?', 'No.', 'Corrections need a clear audit trail.')],
             conclusions=[Choice('tb', 'Which error does a trial balance NOT reveal?', 'Error of principle', ['Single-sided entry', 'Different amounts on each side'])]),

        case('docs', 'Source documents', 'Match Bloom Florists’ paperwork to the right book of prime entry.', 'Documents',
             [('book', 'Book of prime entry', ['Sales day book', 'Purchases day book', 'Cash book', 'Sales returns day book'])],
             [('Invoice out', 'Invoice sent to the hotel for weekly flowers.', {'book': 'Sales day book'}), ('Supplier bill', 'Invoice from the wholesaler for stock on credit.', {'book': 'Purchases day book'}),
              ('Card receipt', 'Card machine settlement into the bank.', {'book': 'Cash book'}), ('Credit note', 'Credit note issued to a customer for wilted roses.', {'book': 'Sales returns day book'})],
             'Lily Marsh, owner, Bloom Florists', 'I have a shoebox of receipts. Where does each go?',
             [('E', 'Can you keep every invoice, credit note and receipt, numbered and dated?', 'Yes, I’ll start a file.'),
              ('E', 'Shall I set up a numbering sequence for your sales invoices?', 'Please.'),
              ('U', 'Do you take cash as well as card?', 'A little cash.'),
              ('N', 'What’s in season?', 'Tulips.'),
              ('P', 'Throw away receipts once they’re entered?', 'Is that OK?', 'Businesses must keep records for years for tax and audit.')],
             conclusions=[Choice('why', 'Why keep source documents?', 'They are the evidence behind every entry, needed for tax and audit', ['They look tidy', 'They are optional'])]),
    ],
    investigations=[
        V('suspense', 'Bank and books don’t agree', 'Bloom Florists’ cash account shows £2,140 but the bank shows £1,690.',
          [('A £450 card payment for flowers was recorded in the bank statement but not in the books.', True), ('No other unreconciled items.', True), ('The difference is exactly £450.', True),
           ('The shop is on the high street.', False), ('The owner uses a tablet.', False)],
          'An unrecorded card payment to a supplier', ['A bank error', 'Theft', 'Too many roses'],
          'Record the missing payment (Dr Purchases, Cr Cash at bank), then re-reconcile and set up bank feeds', ['Adjust the bank figure', 'Ignore £450', 'Write it off to sundries without evidence'],
          calc=('Books £2,140, bank £1,690. Difference (£)?', 450, '£', '2,140 − 1,690 = 450.'),
          steps=['Compare the bank statement to the cash book', 'Identify unrecorded items', 'Post the missing entry with evidence', 'Re-run the reconciliation', 'Review with the client'],
          must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
    ])

# ------------------------------------------------------------ C General ledger and trial balance

ledger = Lab('acc_lab_ledger', 3, 'General Ledger and Trial Balance', 'accountingFirm',
    'Post journals to the ledger, extract and fix trial balances, calculate depreciation and make month-end adjustments.',
    ['Post to and balance ledger accounts', 'Prepare and correct a trial balance', 'Make month-end adjustments'],
    ['bz_acct'], 'al',
    code=[
        Code('ledger', 'Ledger balances', 'Month-end at Ridge Cycles: build the ledger tool.', [
            V3('Input journal lines "debit_account,credit_account,amount". Post each to both accounts and print each account’s closing balance alphabetically as "account: x Dr|Cr" (2 dp; no side if zero).',
               [('Cash,Capital,10000\nEquipment,Cash,4000\nCash,Sales,2500\nRent,Cash,800', 'Capital: 10000.00 Cr\nCash: 7700.00 Dr\nEquipment: 4000.00 Dr\nRent: 800.00 Dr\nSales: 2500.00 Cr'), ('Bank,Loan,500\nLoan,Bank,500', 'Bank: 0.00\nLoan: 0.00'), ('Purchases,Payables,99.5', 'Payables: 99.50 Cr\nPurchases: 99.50 Dr')], M['gl1']),
            V3('The starting program adds the columns the wrong way. Input lines "account amount Dr|Cr". Print total debits and credits (2 dp), then "Trial balance agrees" or "Difference d to suspense (credit|debit side)" — with hints when the difference (in pence) is divisible by 9 (transposition) or even (half posted to the wrong side).',
               [('Cash 7700 Dr\nEquipment 4000 Dr\nRent 800 Dr\nCapital 10000 Cr\nSales 2500 Cr', 'Total debits: 12500.00\nTotal credits: 12500.00\nTrial balance agrees'),
                ('Cash 7700 Dr\nEquipment 4000 Dr\nRent 800 Dr\nCapital 10000 Cr\nSales 2050 Cr', 'Total debits: 12500.00\nTotal credits: 12050.00\nDifference 450.00 to suspense (credit side)\nHint: divisible by 9 - check for a transposition error\nHint: half the difference is 225.00 - check for an amount posted to the wrong side'),
                ('Cash 7700 Dr\nEquipment 4000 Dr\nRent 800 Cr\nCapital 10000 Cr\nSales 2500 Cr', 'Total debits: 11700.00\nTotal credits: 13300.00\nDifference 1600.00 to suspense (debit side)\nHint: half the difference is 800.00 - check for an amount posted to the wrong side')], M['gl2'], None, M['gl2_bug']),
            V3('Depreciation schedules. Input lines "cost residual years SL|RB". SL: (cost − residual) ÷ years; RB: 25% of opening net book value each year. Print "method: Y1 d, Y2 d, … | NBV n" (2 dp).',
               [('10000 1000 3 SL\n10000 0 3 RB', 'SL: Y1 3000.00, Y2 3000.00, Y3 3000.00 | NBV 1000.00\nRB: Y1 2500.00, Y2 1875.00, Y3 1406.25 | NBV 4218.75'), ('2400 0 4 SL', 'SL: Y1 600.00, Y2 600.00, Y3 600.00, Y4 600.00 | NBV 0.00'), ('800 0 1 RB', 'RB: Y1 200.00 | NBV 600.00')], M['gl3']),
        ], skills=['bz_acct']),
    ],
    cases=[
        case('adjust', 'Month-end adjustments', 'Prepare March adjustments for Ridge Cycles.', 'Adjustments needed',
             [('type', 'Adjustment', ['Accrual', 'Prepayment', 'Depreciation', 'None needed'])],
             [('Electric', 'March electricity used but the bill arrives in April (estimate £320).', {'type': 'Accrual'}), ('Insurance', 'Annual insurance of £1,200 paid in March covers April–February too.', {'type': 'Prepayment'}),
              ('Van', 'Van bought in January, 5-year life.', {'type': 'Depreciation'}), ('Wages', 'March wages paid on 31 March.', {'type': 'None needed'})],
             MGR, 'Talk me through the March adjustments.',
             [('E', 'Should I accrue the estimated £320 electricity for March?', 'Yes, matching principle.'),
              ('E', 'Only £100 of the insurance is March’s cost — I’ll prepay £1,100.', 'Correct.'),
              ('U', 'Do we have the fixed asset register?', 'Yes, on the drive.'),
              ('N', 'Is the shop open on Sundays?', 'No.'),
              ('P', 'Expense the whole £1,200 in March to keep it simple?', 'That misstates profit.', 'Costs must be matched to the period they relate to.')],
             conclusions=[Choice('prepaid', 'Insurance prepayment at 31 March', '£1,100', ['£1,200', '£100'])],
             procedure=['Prepare the unadjusted trial balance', 'Calculate accruals and prepayments', 'Post depreciation', 'Prepare the adjusted trial balance', 'Review with the manager'], must=[(0, 1), (0, 2), (1, 3), (2, 3), (3, 4)]),
        case('controls', 'Ledger control accounts', 'Reconcile the receivables control account to the sales ledger.', 'Differences',
             [('fix', 'Correct in', ['Control account', 'Customer ledger'])],
             [('Discount', 'Discounts allowed of £120 posted to customers but not to control.', {'fix': 'Control account'}), ('Customer', 'A £60 invoice posted twice to one customer’s account only.', {'fix': 'Customer ledger'}),
              ('Bad debt', 'Bad debt of £400 written off in the customer account only.', {'fix': 'Control account'}), ('Contra', 'A contra of £75 entered only in the customer account.', {'fix': 'Control account'})],
             MGR, 'Why doesn’t the control account agree?',
             [('E', 'I’ll list each difference and post the corrections to the right ledger.', 'Good.'),
              ('E', 'Is there approval for the £400 bad-debt write-off?', 'Yes, from the director.'),
              ('U', 'Should I age the debts?', 'Yes, useful.'),
              ('N', 'Which customer is biggest?', 'The council.'),
              ('P', 'Post a balancing figure to make it agree?', 'Absolutely not.', 'Plugs hide errors and possible fraud.')],
             conclusions=[Choice('why', 'Why keep a control account?', 'To check the individual ledgers are complete and accurate', ['To duplicate work', 'It is optional decoration'])]),

        case('coa', 'Setting up the chart of accounts', 'Set up the nominal ledger for Ridge Cycles in new software.', 'Proposed accounts',
             [('cat', 'Category', ['Asset', 'Liability', 'Equity', 'Income', 'Expense'])],
             [('Bikes for sale', 'Stock of bikes held for resale.', {'cat': 'Asset'}), ('VAT owed', 'VAT collected on sales, due to HMRC.', {'cat': 'Liability'}),
              ('Repairs income', 'Labour charged for bike repairs.', {'cat': 'Income'}), ('Owner capital', 'Money the owner put in.', {'cat': 'Equity'}), ('Shop rent', 'Monthly rent for the premises.', {'cat': 'Expense'})],
             MGR, 'Is this chart of accounts ready to use?',
             [('E', 'Can we separate repairs income from bike sales so the owner sees both margins?', 'Yes, good idea.'),
              ('E', 'Should VAT owed be a liability control account?', 'Yes.'),
              ('U', 'Should I number accounts by category?', 'Yes, 1000s assets and so on.'),
              ('N', 'Which software colour theme?', 'Blue.'),
              ('P', 'Put everything we can’t classify into “sundries”?', 'That hides information.', 'Overused sundries accounts make reports meaningless.')],
             conclusions=[Choice('vat', 'VAT collected on sales is', 'a liability owed to HMRC', ['income', 'an expense'])]),
    ],
    investigations=[
        V('transpose', 'Trial balance out by £90', 'The trial balance for Ridge Cycles is out by £90.',
          [('The difference, 90, is divisible by 9.', True), ('Repairs income was posted as £1,350 in the ledger but £1,440 on the invoice listing.', True), ('Correcting it makes the trial balance agree.', True),
           ('There are 24 accounts.', False), ('The bookkeeper is new.', False)],
          'Transposition-type error in posting repairs income (1,440 entered as 1,350)', ['Missing account', 'Software bug', 'Too many accounts'],
          'Correct the posting with a journal, clear the suspense account and add a review check against the source listing', ['Leave £90 in suspense', 'Delete the repairs account', 'Plug the difference to sundries'],
          calc=('1,440 − 1,350 = ?', 90, '£', 'The difference is the trial balance error.'),
          steps=['Open a suspense account for the difference', 'Check whether the difference is divisible by 9', 'Compare ledger postings with source documents', 'Post the correcting journal', 'Clear suspense and re-extract the trial balance'],
          must=[(0, 3), (1, 2), (2, 3), (3, 4)]),
    ])

# ------------------------------------------------------------ F Cost and management accounting

cost = Lab('acc_lab_cost', 6, 'Cost and Management Accounting', 'accountingFirm',
    'Run break-even and target-profit analysis, compute variances, price products and advise managers on decisions.',
    ['Apply cost–volume–profit analysis', 'Calculate and explain variances', 'Support management decisions'],
    ['bz_acct', 'bz_ops'], 'ac',
    code=[
        Code('cvp', 'Break-even and target profit', 'Ticket MA-4: Forge Coffee Roasters wants a CVP tool.', [
            V3('The starting program ignores variable cost. Input lines "fixed_costs price variable_cost_per_unit". Print "Contribution c per unit; break-even n units" (c 2 dp, units rounded up).',
               [('50000 25 15\n12000 8 5', 'Contribution 10.00 per unit; break-even 5000 units\nContribution 3.00 per unit; break-even 4000 units'), ('1000 3 1', 'Contribution 2.00 per unit; break-even 500 units'), ('100 7 4', 'Contribution 3.00 per unit; break-even 34 units')], M['cv1'], None, M['cv1_bug']),
            V3('Input lines "fixed price variable budget_units target_profit". Print "Break-even b; margin of safety m%; units for target profit t" (m 1 dp; units rounded up).',
               [('50000 25 15 7000 20000', 'Break-even 5000; margin of safety 28.6%; units for target profit 7000'), ('12000 8 5 5000 3000', 'Break-even 4000; margin of safety 20.0%; units for target profit 5000'), ('100 7 4 50 50', 'Break-even 34; margin of safety 32.0%; units for target profit 50')], M['cv2']),
            V3('Material variances. Input "standard_qty_for_actual_output standard_price actual_qty actual_price". Price = (SP − AP) × AQ, usage = (SQ − AQ) × SP. Print each with F (favourable) or A (adverse), and the total (2 dp).',
               [('1000 5 1100 4.8', 'Material price variance: 220.00 F\nMaterial usage variance: 500.00 A\nTotal material variance: 280.00 A'), ('500 2 480 2.1', 'Material price variance: 48.00 A\nMaterial usage variance: 40.00 F\nTotal material variance: 8.00 A'), ('100 1 100 1', 'Material price variance: 0.00\nMaterial usage variance: 0.00\nTotal material variance: 0.00')], M['cv3']),
        ], skills=['bz_acct']),
    ],
    problems=[
        D('price', 'Pricing a new coffee blend', 'Forge sells a blend at price p per bag; variable cost £6 per bag; monthly fixed costs £6,000. Demand falls as price rises: units = 4,000 − 150 × p.',
          [I('p', 'Price per bag', 7, 20, 0.5, 7, '£')],
          [O('Q', 'Bags sold per month', '4000-150*p', 'bags', 0), O('P', 'Monthly profit', '((4000-150*p)*(p-6)-6000)/1000', '£k', 2), O('M', 'Margin per bag', '(p-6)/p*100', '%', 1)],
          {'p': 7}, ['Q', 'P', 'M'],
          ([ge('P', 6, 'Profit at least £6k a month')], [ge('Q', 1800, 'Sell at least 1,800 bags (roaster capacity use)')], [ge('M', 50, 'At least 50% margin per bag')]),
          {'p': 12}),
    ],
    cases=[
        case('decision', 'Make or buy decision', 'Forge can make its own coffee bags or buy them in.', 'Cost information',
             [('rel', 'Relevant to the decision?', ['Relevant', 'Not relevant'])],
             [('Materials', 'Materials to make bags: £0.20 each.', {'rel': 'Relevant'}), ('Rent', 'Factory rent, paid whatever we decide.', {'rel': 'Not relevant'}, 'Committed fixed costs don’t change.'),
              ('Supplier', 'Supplier price: £0.35 each.', {'rel': 'Relevant'}), ('Sunk', 'Last year’s £5,000 market research.', {'rel': 'Not relevant'}, 'Sunk costs are irrelevant.')],
             'Ben Forge, managing director', 'Should we make our own bags?',
             [('E', 'Which costs would actually change if we made them ourselves?', 'Materials and two hours of labour a day.'),
              ('E', 'Is there spare machine capacity, or would we lose other work?', 'Spare capacity on Fridays.'),
              ('U', 'Is quality the same?', 'Supplier bags are slightly better.'),
              ('N', 'Which bag colour?', 'Black.'),
              ('P', 'Include the market research cost in the comparison?', 'It’s already spent.', 'Sunk costs mislead decisions.')],
             conclusions=[Choice('rule', 'Relevant costs are', 'future, incremental cash flows that differ between options', ['all costs ever incurred', 'only fixed costs'])]),
        case('budget', 'Budget review meeting', 'Present the quarterly budget-versus-actual report to the managing director.', 'Variances',
             [('flag', 'Action', ['Investigate', 'Note only'])],
             [('Beans', 'Green bean cost 18% over budget.', {'flag': 'Investigate'}, 'Material and significant.'), ('Stationery', 'Stationery £40 over.', {'flag': 'Note only'}),
              ('Sales', 'Sales 12% below budget.', {'flag': 'Investigate'}), ('Energy', 'Energy 2% under budget.', {'flag': 'Note only'})],
             'Ben Forge, managing director', 'Why are we behind plan?',
             [('E', 'Bean prices rose 18% after the harvest failure; shall we review supplier contracts?', 'Yes.'),
              ('E', 'Sales fell after a big café client closed — can we look at new channels?', 'Good idea.'),
              ('U', 'Should we flex the budget for lower volume?', 'Yes, it’s fairer.'),
              ('N', 'Is the coffee good this month?', 'Excellent.'),
              ('P', 'Blame the production team for everything?', 'That’s not fair.', 'Variance analysis looks for causes, not scapegoats.')],
             conclusions=[Choice('flex', 'A flexed budget', 'adjusts the budget to actual activity for fair comparison', ['ignores volume', 'is always the original budget'])],
             doc=('Management report', [
                 ('Key variances', [('Mentions beans or materials', [r'bean|material']), ('Quantifies', [r'\d+%'])],
                  'Green bean costs were 18% over budget because of a poor harvest, and sales were 12% below budget after a major café client closed in February.'),
                 ('Recommendations', [('Recommends an action', [r'recommend|review|renegotiat|new channel']), ('Mentions a flexed budget or forecast', [r'flex|forecast|reforecast'])],
                  'We recommend reviewing supplier contracts, targeting online subscriptions as a new channel, and reporting against a flexed budget so performance is judged at actual volumes.')])),
    ],
    investigations=[
        V('margin', 'Best-selling product losing money', 'The espresso blend is Forge’s top seller, but profit fell when its sales grew.',
          [('Its price hasn’t changed in 3 years while bean costs rose 30%.', True), ('Contribution per bag is now £0.40 after a 25% trade discount.', True), ('Overheads are allocated by sales volume, hiding the true cost.', True),
           ('The bag is red.', False), ('It is popular with students.', False)],
          'Low contribution from out-of-date pricing and heavy trade discounts, hidden by volume-based overhead allocation', ['The red bag', 'Students', 'Bad weather'],
          'Recalculate product costs (consider activity-based costing), review prices and discount terms, and monitor contribution by product', ['Sell more at the same price', 'Stop all discounts overnight without analysis', 'Ignore it'],
          calc=('Price £8.00, trade discount 25%, variable cost £5.60. Contribution per bag (£)?', 0.4, '£', '8 × 0.75 − 5.60 = 0.40.'),
          steps=['Calculate contribution by product', 'Review overhead allocation', 'Model price and discount changes', 'Agree new terms with the sales team', 'Monitor contribution monthly'],
          must=[(0, 2), (1, 2), (2, 3), (3, 4)]),
    ])

